"""Summarize node sequences without changing the node."""
import json
import os
import re
import sys

NAME = re.compile(r"(obs|must)\.([0-9]{12}|active)\.jsonl")


def strict_json(data):
    def reject_constant(value):
        raise ValueError(value)

    return json.loads(data.decode("utf-8"), parse_constant=reject_constant)


def integer(value):
    return type(value) is int


def add_bad(bad, name, line, why):
    bad.append({"file": name, "line": line, "why": why})


def summarize(folder):
    with os.scandir(folder) as listing:
        entries = {entry.name: entry for entry in listing}
    bad = []
    channels = {}
    distinct = {}
    for ch in ("obs", "must"):
        files = []
        for name, entry in entries.items():
            match = NAME.fullmatch(name)
            if match and match.group(1) == ch and entry.is_file(follow_symlinks=False):
                part = match.group(2)
                files.append((part == "active", 0 if part == "active" else int(part), name))
        seqs = []
        for _, _, name in sorted(files):
            with open(os.path.join(folder, name), "rb") as stream:
                parts = stream.read().split(b"\n")
            for line, raw in enumerate(parts[:-1], 1):
                try:
                    record = strict_json(raw)
                except (UnicodeError, ValueError):
                    add_bad(bad, name, line, "bad_json")
                    continue
                if not isinstance(record, dict) or not integer(record.get("seq")) or record["seq"] < 1:
                    add_bad(bad, name, line, "no_seq")
                else:
                    seqs.append(record["seq"])
            if parts[-1]:
                add_bad(bad, name, len(parts), "torn")
        unique = sorted(set(seqs))
        distinct[ch] = unique
        channels[ch] = {
            "count": len(seqs),
            "first": unique[0] if unique else None,
            "last": unique[-1] if unique else None,
            "missing": [[left + 1, right - 1] for left, right in zip(unique, unique[1:]) if right > left + 1],
            "dup": sorted(seq for seq in set(seqs) if seqs.count(seq) > 1),
            "next_seq": None,
            "unacked": None,
            "stale_next": None,
        }

    state = entries.get("state.json")
    if state is not None:
        try:
            if not state.is_file(follow_symlinks=False):
                raise ValueError("state is not a regular file")
            with open(os.path.join(folder, "state.json"), "rb") as stream:
                value = strict_json(stream.read())
            if not isinstance(value, dict) or not isinstance(value.get("channels"), dict):
                raise ValueError("invalid state")
        except (OSError, UnicodeError, ValueError):
            add_bad(bad, "state.json", None, "bad_state")
        else:
            invalid = False
            for ch in ("obs", "must"):
                fields = value["channels"].get(ch)
                if (not isinstance(fields, dict) or not integer(fields.get("next_seq"))
                        or (ch == "must" and not integer(fields.get("acked_upto")))):
                    invalid = True
                    continue
                info = channels[ch]
                info["next_seq"] = fields["next_seq"]
                if ch == "must":
                    info["unacked"] = sum(seq > fields["acked_upto"] for seq in distinct[ch])
                if info["last"] is not None:
                    info["stale_next"] = fields["next_seq"] != info["last"] + 1
            if invalid:
                add_bad(bad, "state.json", None, "bad_state")
    bad.sort(key=lambda item: (item["file"], 0 if item["line"] is None else item["line"], item["why"]))
    return {"v": 1, "channels": channels, "bad": bad}


def main(argv=None):
    args = sys.argv[1:] if argv is None else argv
    if len(args) != 1 or not os.path.isdir(args[0]):
        return 2
    try:
        result = summarize(args[0])
    except OSError:
        return 2
    print(json.dumps(result, ensure_ascii=False, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    sys.exit(main())
